Q: Rendering problems when zooming and panning on canvas A: <p>In the end I was able to solve it with a total rewrite.</p>
<p>See  <a href="https://codepen.io/r-w-c/pen/dywRKJL" rel="nofollow noreferrer">https://codepen.io/r-w-c/pen/dywRKJL</a></p>
<p>Here is the complete Javascript Code. The relevant functions are zoom, pan, panScreen and animatePan.</p>
<pre><code>    const IMGURL = &quot;https://i.imgur.com/Z5mPZ2Y.jpg&quot;;

    const ZOOMINLEVEL = 1.2;
    const ZOOMOUTLEVEL = 0.8;
    const MINZOOMLEVEL = 0.1;
    const MAXZOOMLEVEL = 15;
    const CANVASWIDTH = 600;
    const CANVASHEIGHT = 400;
    const PANSTEP = 20;
    const DEFAULTCURSOR = &quot;crosshair&quot;;
    const MOUSEDOWNCURSOR = &quot;grab&quot;;
    const ZOOMINCURSOR = &quot;zoom-in&quot;;
    const ZOOMOUTCURSOR = &quot;zoom-out&quot;;
    const IMAGESMOOTHINGENABLED = true;

    var currentZoomLevel = 1;
    var isDragging = false;
    var dragStartPosition = { x: 0, y: 0 };

    var canvas,
      context,
      image,
      currentTransformedCursor,
      scaledImgWidth,
      scaledImgHeight,
      startX,
      startY,
      canvasCenterX,
      canvasCenterY,
      zoomLevelTxt,
      mousePos,
      transformedMousePos,
      scale,
      currentRotation;

    window.onload = () =&gt; {
      loadImage();
      addEventListeners();
    };

    function loadImage() {
      canvas = document.getElementById(&quot;canvas&quot;);
      canvas.width = CANVASWIDTH;
      canvas.height = CANVASHEIGHT;
      context = canvas.getContext(&quot;2d&quot;);
      context.imageSmoothingEnabled = IMAGESMOOTHINGENABLED;

      zoomLevelTxt = document.getElementById(&quot;zoom-level&quot;);
      mousePos = document.getElementById(&quot;mouse-pos&quot;);
      transformedMousePos = document.getElementById(&quot;transformed-mouse-pos&quot;);

      image = new Image();

      image.onload = function () {
        init();
        reset();
      };
      image.src = IMGURL;
    }

    function init() {
      scale = Math.min(canvas.width / image.width, canvas.height / image.height);
      scaledImgWidth = image.width * scale;
      scaledImgHeight = image.height * scale;
      startX = (canvas.width - scaledImgWidth) / 2;
      startY = (canvas.height - scaledImgHeight) / 2;
      canvasCenterX = canvas.width / 2;
      canvasCenterY = canvas.height / 2;
      currentTransformedCursor = { x: canvasCenterX, y: canvasCenterY };
      canvas.style.cursor = DEFAULTCURSOR;
      context.save();

      //overlayTest(); //Temporary, for testing
    }

    function drawImageToCanvas() {
      context.save();
      context.setTransform(1, 0, 0, 1, 0, 0);
      context.clearRect(0, 0, canvas.width, canvas.height);
      context.restore();
      context.drawImage(image, startX, startY, scaledImgWidth, scaledImgHeight);
    }

    function getTransformedPoint(x, y) {
      const originalPoint = new DOMPoint(x, y);
      return context.getTransform().invertSelf().transformPoint(originalPoint);
    }

    function onMouseDown(event) {
      isDragging = true;
      canvas.style.cursor = MOUSEDOWNCURSOR;
      dragStartPosition = getTransformedPoint(event.offsetX, event.offsetY);
    }

    function onMouseMove(event) {
      canvas.style.cursor = DEFAULTCURSOR;
      currentTransformedCursor = getTransformedPoint(event.offsetX, event.offsetY);

      displayMousePos(event.offsetX, event.offsetY);
      event.preventDefault();

      if (isDragging) {
        pan(
          currentTransformedCursor.x - dragStartPosition.x,
          currentTransformedCursor.y - dragStartPosition.y
        );
      }
    }

    function onMouseUp() {
      isDragging = false;
      canvas.style.cursor = DEFAULTCURSOR;
    }

    function onWheel(event) {
      zoom(event.deltaY &lt; 0 ? ZOOMINLEVEL : ZOOMOUTLEVEL);
      event.preventDefault();
    }

    function zoom(zoomLevel) {
      if (currentZoomLevel == MINZOOMLEVEL &amp;&amp; zoomLevel &lt;= 1) {
        return;
      }

      if (currentZoomLevel == MAXZOOMLEVEL &amp;&amp; zoomLevel &gt;= 1) {
        return;
      }

      currentZoomLevel = Math.min(
        Math.max(currentZoomLevel * zoomLevel, MINZOOMLEVEL),
        MAXZOOMLEVEL
      );
      displayZoomLevel();

      canvas.style.cursor = zoomLevel &gt; 1 ? ZOOMINCURSOR : ZOOMOUTCURSOR;
      context.translate(currentTransformedCursor.x, currentTransformedCursor.y);
      context.scale(zoomLevel, zoomLevel);
      context.translate(-currentTransformedCursor.x, -currentTransformedCursor.y);
      drawImageToCanvas();
    }

    function pan(x, y) {
      context.translate(x, y);
      drawImageToCanvas();
    }
    function rotate(degrees) {
      context.translate(canvasCenterX, canvasCenterY);
      context.rotate((Math.PI / 180) * degrees);
      context.translate(-canvasCenterX, -canvasCenterY);
      drawImageToCanvas();
    }

    function mirror() {
      context.translate(canvasCenterX, canvasCenterY);
      context.scale(-1, 1);
      context.translate(-canvasCenterX, -canvasCenterY);
      drawImageToCanvas();
    }

    function flip() {
      context.translate(canvasCenterX, canvasCenterY);
      context.scale(1, -1);
      context.translate(-canvasCenterX, -canvasCenterY);
      //currentRotation = (currentRotation + 360 + 180) % 360;
      drawImageToCanvas();
    }

    function reset() {
      context.restore();
      context.save();
      drawImageToCanvas();
      currentZoomLevel = 1;
      currentRotation = 0;
      displayZoomLevel();
      canvas.style.cursor = DEFAULTCURSOR;
    }

    function addEventListeners() {
      canvas.addEventListener(&quot;mousedown&quot;, onMouseDown);
      canvas.addEventListener(&quot;mousemove&quot;, onMouseMove);
      canvas.addEventListener(&quot;mouseup&quot;, onMouseUp);
      canvas.addEventListener(&quot;wheel&quot;, onWheel);
      document.getElementById(&quot;reset&quot;).addEventListener(&quot;click&quot;, function () {
        reset();
      });
      document.getElementById(&quot;center&quot;).addEventListener(&quot;click&quot;, function () {
        center();
      });
      document.getElementById(&quot;zoomIn&quot;).addEventListener(&quot;click&quot;, function (event) {
        currentTransformedCursor = {
          x: canvasCenterX,
          y: canvasCenterY
        };
        zoom(ZOOMINLEVEL);
      });
      document
        .getElementById(&quot;zoomOut&quot;)
        .addEventListener(&quot;click&quot;, function (event) {
          currentTransformedCursor = {
            x: canvasCenterX,
            y: canvasCenterY
          };
          zoom(ZOOMOUTLEVEL);
        });
      document.getElementById(&quot;rotateRight&quot;).addEventListener(&quot;click&quot;, function () {
        currentRotation = (currentRotation + 90) % 360;
        rotate(90);
      });
      document
        .getElementById(&quot;rotateLeft&quot;)
        .addEventListener(&quot;click&quot;, function (event) {
          currentRotation = (currentRotation + 270) % 360;
          rotate(-90);
        });
      document.getElementById(&quot;mirror&quot;).addEventListener(&quot;click&quot;, function (event) {
        mirror();
      });
      document.getElementById(&quot;flip&quot;).addEventListener(&quot;click&quot;, function (event) {
        flip();
      });
      document
        .getElementById(&quot;panLeft&quot;)
        .addEventListener(&quot;click&quot;, function (event) {
          // Move visually Left (-X)
          panScreen(-PANSTEP, 0);
        });

      document
        .getElementById(&quot;panRight&quot;)
        .addEventListener(&quot;click&quot;, function (event) {
          // Move visually Right (+X)
          panScreen(PANSTEP, 0);
        });

      document.getElementById(&quot;panUp&quot;).addEventListener(&quot;click&quot;, function (event) {
        // Move visually Up (-Y)
        panScreen(0, -PANSTEP);
      });

      document
        .getElementById(&quot;panDown&quot;)
        .addEventListener(&quot;click&quot;, function (event) {
          // Move visually Down (+Y)
          panScreen(0, PANSTEP);
        });
    }

    function displayMousePos(x, y) {
      var transX = currentTransformedCursor.x.toFixed(2);
      var transY = currentTransformedCursor.y.toFixed(2);
      mousePos.innerText = `Original (${x}, ${y})`;
      transformedMousePos.innerText = `Transformed (${transX}, ${transY})`;
    }

    function displayZoomLevel() {
      zoomLevelTxt.innerText = +currentZoomLevel.toFixed(2);
    }

    function panScreen(screenDx, screenDy) {
      const transform = context.getTransform();
      const inverse = transform.invertSelf();

      const p0 = inverse.transformPoint(new DOMPoint(0, 0));
      const p1 = inverse.transformPoint(new DOMPoint(screenDx, screenDy));

      const localDx = p1.x - p0.x;
      const localDy = p1.y - p0.y;

      // CHANGED: Use the smooth animation helper
      animatePan(localDx, localDy);
    }

    function center() {
      // 1. Calculate the center of the image in &quot;Local&quot; coordinates (untransformed)
      const localCX = startX + scaledImgWidth / 2;
      const localCY = startY + scaledImgHeight / 2;

      // 2. Find where that center currently is on the &quot;Screen&quot; (transformed)
      const transform = context.getTransform();
      const screenCP = transform.transformPoint(new DOMPoint(localCX, localCY));

      // 3. Calculate the difference (delta) between the Canvas Center and the Image Center
      const dx = canvas.width / 2 - screenCP.x;
      const dy = canvas.height / 2 - screenCP.y;

      // 4. Move the image by that delta using our screen-space panner
      panScreen(dx, dy);
    }

    let currentAnimationId = null;

    function animatePan(totalDx, totalDy, duration = 400) {
      // 1. Cancel any active animation so they don't fight each other
      if (currentAnimationId) {
        cancelAnimationFrame(currentAnimationId);
      }

      const startTime = performance.now();
      let lastProgress = 0;

      function step(currentTime) {
        // 2. Calculate how much time has passed (0.0 to 1.0)
        let progress = (currentTime - startTime) / duration;
        if (progress &gt; 1) progress = 1;

        // 3. Apply Easing (Ease Out Quad) - makes it feel &quot;natural&quot;
        // Formula: t * (2 - t)
        const easedProgress = progress * (2 - progress);

        // 4. Calculate how much we need to move *just for this frame*
        // We compare where we should be now (easedProgress) vs where we were last frame (lastProgress)
        const frameDelta = easedProgress - lastProgress;

        const frameX = totalDx * frameDelta;
        const frameY = totalDy * frameDelta;

        // 5. Apply the small movement
        pan(frameX, frameY);

        lastProgress = easedProgress;

        // 6. Continue or Stop
        if (progress &lt; 1) {
          currentAnimationId = requestAnimationFrame(step);
        } else {
          currentAnimationId = null;
        }
      }

      // Start the loop
      currentAnimationId = requestAnimationFrame(step);
    }
</code></pre>

Q: iOS 26 Glass Effect and toolbarColorScheme A: <p>Try declaring your toolbar item like this:</p>
<pre><code>ToolbarItem(placement: .topBarTrailing) {
    Button {
        // Do something here
    } label: {
        // Your custom image / text here
        Text(&quot;Button&quot;)
    }
}
.sharedBackgroundVisibility(.hidden)
</code></pre>
<p>The <code>sharedBackgroundVisibility</code> bit is the important one.</p>

Q: adding a new wpdb class in wordpress A: <p>I have already done this kind of thing recently, you can use this code if you want. But you must have to make sure to use this inside a hook that run after WordPress load, maybe <code>init</code> or any hook where you need it, if you want to use it in a file that does not care if WordPress loaded or not then you must have to include <code>wp-load.php</code>. Check my code which runs after the Elementor Pro form submission.</p>
<pre class="lang-php prettyprint-override"><code>&lt;?php

add_action( 'elementor_pro/forms/new_record', function($record, $handler) {

    $sent_data = $record-&gt;get(&quot;sent_data&quot;);

    if ($sent_data &amp;&amp; is_array($sent_data)) {

        $first_name = isset($sent_data['first_name']) ? $sent_data['first_name'] : '';
        $last_name  = isset($sent_data['last_name']) ? $sent_data['last_name'] : '';
        $email      = isset($sent_data['email']) ? $sent_data['email'] : '';
        $message    = isset($sent_data['message']) ? $sent_data['message'] : '';

        if (
            defined('NEWSLETTER_DB_NAME') &amp;&amp;
            defined('NEWSLETTER_DB_USER') &amp;&amp;
            defined('NEWSLETTER_DB_PASSWORD') &amp;&amp;
            defined('NEWSLETTER_DB_HOST')
        ) {

            /**
             * - External DB Connection
             */

            $db_host     = NEWSLETTER_DB_HOST;
            $db_name     = NEWSLETTER_DB_NAME;
            $db_user     = NEWSLETTER_DB_USER;
            $db_password = NEWSLETTER_DB_PASSWORD;

            $external_db = new wpdb($db_user, $db_password, $db_name, $db_host);
            $table_name  = 'newsContact';

            // check if email exists
            $existing = $external_db-&gt;get_var(
                $external_db-&gt;prepare(
                    &quot;SELECT COUNT(*) FROM $table_name WHERE email = %s&quot;,
                    $email
                )
            );

            if ($existing &gt; 0) {

                $external_db-&gt;update(
                    $table_name,
                    array(
                        'displayName'     =&gt; $first_name . ' ' . $last_name,
                        'active'          =&gt; 'y',
                        'updateTimestamp' =&gt; current_time('mysql')
                    ),
                    array('email' =&gt; $email)
                );

            } else {

                $external_db-&gt;insert(
                    $table_name,
                    array(
                        'newsGroupID'     =&gt; 2,
                        'email'           =&gt; $email,
                        'displayName'     =&gt; $first_name . ' ' . $last_name,
                        'active'          =&gt; 'y',
                        'insertTimestamp' =&gt; current_time('mysql'),
                        'updateTimestamp' =&gt; current_time('mysql'),
                        'uniqID'          =&gt; uniqid()
                    )
                );
            }

            error_log('Inserted ID: ' . $external_db-&gt;insert_id);

        } else {

            error_log('Newsletter DB constants not defined.');
        }
    }

}, 10, 2 );


also make sure to put your external db constant in wp-config.php

define(&quot;NEWSLETTER_DB_NAME&quot;, &quot;db name goes here&quot;);
define(&quot;NEWSLETTER_DB_USER&quot;, &quot;db user goes here&quot;);
define(&quot;NEWSLETTER_DB_PASSWORD&quot;, &quot;db password goes here&quot;);
define(&quot;NEWSLETTER_DB_HOST&quot;, &quot;db host goes here&quot;);
</code></pre>
